-- Package 3 (0074 + 0075) — PREFLIGHT. READ ONLY: one SELECT, changes nothing.
-- Run once on live immediately before pkg3_apply.sql. Part 1: every row must be ok = true, or the package
-- is not applied. Part 2: information only. The rows of 0074_preflight.sql unchanged, plus 0075's
-- "does not exist yet" row (its "0074 is applied" row is checked inside pkg3_apply.sql, after 0074).
with checks(part, item, ok, detail) as (
  select 1, '0074 none of 0074''s tables exists yet', not exists (select 1 from pg_tables where schemaname = 'public' and tablename in ('player_blocks','reports','blocked_terms','account_suspensions')), ''
  union all select 1, '0074 none of 0074''s functions exists yet', not exists (select 1 from pg_proc where pronamespace = 'public'::regnamespace and proname in ('match_players_block_guard','players_blocked','block_player','unblock_player','my_blocked_players','accept_community_rules','my_rules_accepted','message_has_blocked_term','report_content','assert_active','admin_reports','admin_report_messages','admin_resolve_report','admin_hide_message','admin_suspend','admin_unsuspend','my_account_status','send_feedback','my_recent_players')), ''
  union all select 1, '0074 chat read policy is the 0025 one (members)', (select qual from pg_policies where tablename = 'match_messages' and policyname = 'match_messages: members read') = 'is_match_member(match_id)', coalesce((select qual from pg_policies where tablename = 'match_messages' and policyname = 'match_messages: members read'), 'missing')
  union all select 1, '0074 profiles.rules_accepted_at does not exist yet', not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'profiles' and column_name = 'rules_accepted_at'), ''
  union all select 1, '0074 post_match: the version 0074 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '6a8feb9a5b8c59e81d8d72ac49076635' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'post_match'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'post_match'), 'missing')
  union all select 1, '0074 join_match: the version 0074 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '47e042026bc084f8da0664020b77e1fb' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'join_match'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'join_match'), 'missing')
  union all select 1, '0074 decide_join: the version 0074 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '504c193753ecdda87b461204e1e0243f' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'decide_join'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'decide_join'), 'missing')
  union all select 1, '0074 update_match: the version 0074 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'efc91a08d70e84de15fced731b99a03c' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'update_match'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'update_match'), 'missing')
  union all select 1, '0074 set_match_status: the version 0074 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '883dc68e447d0f8a5af681d8f395bf3b' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'set_match_status'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'set_match_status'), 'missing')
  union all select 1, '0074 remove_player: the version 0074 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '16aa48b9507019f62b35e77d4fb63763' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'remove_player'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'remove_player'), 'missing')
  union all select 1, '0074 resolve_court: the version 0074 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'a1fb427e8c034c6fee12876f342d3460' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'resolve_court'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'resolve_court'), 'missing')
  union all select 1, '0074 match_message_guard: the version 0074 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'd58b98d66bb5d8d5033a99069c411615' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_message_guard'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_message_guard'), 'missing')
  union all select 1, '0074 match_message_notify: the version 0074 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'c063c6d3f6071aa1a6446682cad26491' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_message_notify'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_message_notify'), 'missing')
  union all select 1, '0074 match_messages_list: the version 0074 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'c0159407235a7e78b86cc3fa11592861' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_messages_list'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_messages_list'), 'missing')
  union all select 1, '0074 open_matches: the version 0074 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = 'fe591842860b76aa55f31440f4c0ee72' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'open_matches'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'open_matches'), 'missing')
  union all select 1, '0074 match_board: the version 0074 replaces', (select count(*) = 1 and max(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g'))) = '7ee31e25c3b937e5bf1316d8907d1117' from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_board'), coalesce((select string_agg(md5(regexp_replace(prosrc, '[ \t\r]+(\n|$)', '\1', 'g')), ',') from pg_proc where pronamespace = 'public'::regnamespace and proname = 'match_board'), 'missing')
  union all select 2, '0074 admins who can moderate (is_admin): at least one is needed to review reports', true, (select count(*)::text from profiles where 'admin' = any(roles))
  union all select 2, '0074 players who have sent a message (each accepts the community rules before the next one)', true, (select count(distinct profile_id)::text from match_messages)
  union all select 1, '0075 admin_blocks_received does not exist yet', to_regproc('public.admin_blocks_received') is null, ''
)
select part, item, ok, detail from checks order by part, item;
